    </div></div><link rel="stylesheet" href="assets/admin-tech.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script>const sidebar=document.querySelector('.js-sidebar'),toggleBtn=document.querySelector('.js-toggle-btn'),overlay=document.querySelector('.js-overlay');function toggleSidebar(){if(!sidebar||!overlay)return;sidebar.classList.toggle('active');overlay.classList.toggle('active')}if(toggleBtn)toggleBtn.addEventListener('click',toggleSidebar);if(overlay)overlay.addEventListener('click',toggleSidebar)</script></body></html>